import sys


def main():
    lines = sys.stdin.read().split("\n")
    n = int(lines[0])
    counts = {}
    out = []
    for k in range(1, n + 1):
        parts = lines[k].split()
        if parts[0] == "1":
            x = int(parts[1])
            counts[x] = counts.get(x, 0) + 1
        else:
            if not counts:
                out.append("-1")
                continue
            best = None
            for key in counts:
                if best is None or key < best:
                    best = key
            counts[best] -= 1
            if counts[best] == 0:
                del counts[best]
            out.append(str(best))
    print("\n".join(out))


main()
